def transpose(m):
    if not m or not m[0]:
        return []

    # Find the maximum number of columns
    max_cols = max(len(row) for row in m)

    # Create transposed matrix, handling irregular rows
    result = []
    for i in range(max_cols):
        new_row = []
        for row in m:
            if i < len(row):
                new_row.append(row[i])
        result.append(new_row)

    return result


